def validate_windows_scm_service_entry_contract(sources):
    verify = sources["verify"]
    requirements = sources["requirements"]
    hardening = sources["hardening"]
    core_main = sources["core_main"]
    windows = sources["windows_source"]
    config = sources["config_source"]

    require_text(
        verify,
        'echo "== (3b-iii-d9ca) Windows SCM-owned service entry authority (R-S11ak/R-S11e-51) =="',
        "Windows SCM service-entry source gate",
    )

    core_entry = extract_between(
        core_main,
        "pub fn core_main() -> Option<Vec<String>> {",
        '\n    if !crate::common::global_init()',
        "Windows early SCM process entry",
    )
    exact_entry = extract_between(
        core_entry,
        '#[cfg(windows)]\n    if service_supervisor_role == crate::common::ServiceSupervisorRole::Exact {',
        "\n    #[cfg(target_os = \"macos\")]",
        "Windows exact service-supervisor entry",
    )
    require_order(
        exact_entry,
        (
            "if !crate::platform::windows::bootstrap() {",
            "Windows service process bootstrap failed closed",
            "std::process::exit(1);",
            "if let Err(err) = crate::start_os_service() {",
            "Windows service-control dispatcher authority failed closed",
            "std::process::exit(1);",
            "return None;",
        ),
        "Windows dispatcher-before-service-initialization authority",
    )
    if core_main.index("if let Err(err) = crate::start_os_service()") >= core_main.index(
        "if !crate::common::global_init()"
    ):
        raise VerificationError("Windows service dispatcher does not precede global initialization")
    for forbidden, label in (
        ("crate::common::global_init()", "global initialization"),
        ("crate::load_custom_client()", "custom-client initialization"),
        ("initialize_windows_service_owned_root", "machine-config initialization"),
        ("hbb_common::init_log", "service log initialization"),
    ):
        if forbidden in exact_entry:
            raise VerificationError(f"Windows exact pre-dispatch entry retains {label}")

    dispatcher = extract_between(
        windows,
        "pub fn start_os_service() -> ResultType<()> {",
        "\n}\n\nconst SERVICE_TYPE",
        "Windows result-bearing SCM dispatcher",
    )
    require_order(
        dispatcher,
        (
            "windows_service::service_dispatcher::start(crate::get_app_name(), ffi_service_main)",
            '.map_err(|err| anyhow!("Failed to connect the Windows service process to the SCM: {err}"))',
        ),
        "Windows result-bearing SCM dispatcher",
    )
    if "if let Err" in dispatcher or "log::error!" in dispatcher:
        raise VerificationError("Windows SCM dispatcher still swallows its error")

    service_preamble = extract_between(
        windows,
        'async fn run_service(arguments: Vec<OsString>) -> ResultType<()> {',
        "\n    let status_handle = service_control_handler::register",
        "Windows SCM service-entry preamble",
    )
    for forbidden, label in (
        ("crate::common::global_init()", "global initialization"),
        ("crate::load_custom_client()", "custom-client initialization"),
        ("initialize_windows_service_owned_root", "machine-config initialization"),
        ("hbb_common::init_log", "service log initialization"),
    ):
        if forbidden in service_preamble:
            raise VerificationError(f"Windows ServiceMain performs {label} before handler registration")

    service_initialization = extract_between(
        windows,
        "let service_name = arguments",
        "\n    let (credential_request_tx, mut credential_request_rx)",
        "Windows SCM-owned service initialization",
    )
    require_order(
        service_initialization,
        (
            "let service_name = arguments",
            ".first()",
            ".filter(|name| !name.is_empty())",
            'ok_or_else(|| anyhow!("SCM did not supply the Windows service name"))?;',
            "let status_handle = service_control_handler::register(service_name, event_handler)?;",
            "ServiceState::StartPending",
            "if !crate::common::global_init() {",
            "crate::load_custom_client();",
            "let program_data = program_data_dir()?;",
            "Config::initialize_windows_service_owned_root(&program_data, true)?;",
            'hbb_common::init_log(false, "service");',
            "if let Err(err) = initialization {",
            "ServiceState::Stopped",
            "ServiceExitCode::ServiceSpecific(1)",
            "return Err(err);",
        ),
        "Windows handler-status-config-listener initialization order",
    )

    bootstrap = extract_between(
        windows,
        "pub fn bootstrap() -> bool {",
        "\n}\n\n#[cfg(not(debug_assertions))]",
        "Windows ordinary process bootstrap",
    )
    require_order(
        bootstrap,
        (
            "if crate::common::is_service_owned_server_process() {",
            "Config::initialize_windows_service_owned_root(&program_data, false)",
        ),
        "Windows exact child read-only config bootstrap",
    )
    if (
        "is_service_supervisor_process()" in bootstrap
        or "initialize_windows_service_owned_root(&program_data, true)" in bootstrap
    ):
        raise VerificationError("Windows pre-dispatch bootstrap retains supervisor write authority")

    writer = extract_between(
        config,
        "pub fn initialize_windows_service_owned_root(",
        "\n    #[cfg(target_os = \"linux\")]",
        "Windows machine-config writer receiver",
    )
    require_order(
        writer,
        (
            "if !windows_config_acl::current_process_is_local_system()? {",
            "Windows service-owned config root requires the LocalSystem token",
            "windows_machine_config::initialize(root, write_authority)",
        ),
        "Windows independent LocalSystem writer proof",
    )

    requirement = extract_html_requirement(
        requirements, "R-S11ak", "Windows SCM service-entry requirement"
    )
    for text, label in (
        (
            "run only the mandatory process-wide safe-DLL loader bootstrap and then call a result-bearing service dispatcher",
            "early result-bearing dispatcher clause",
        ),
        (
            "Only the SCM-invoked service entry may initialize the durable machine-config writer",
            "SCM-only config writer clause",
        ),
        (
            "derive a nonempty registration name from SCM's first <code>ServiceMain</code> argument",
            "SCM-owned service-name clause",
        ),
        (
            "making SCM ownership and OS principal two distinct proofs",
            "conjunctive SCM/principal authority clause",
        ),
    ):
        require_text(requirement, text, label)
    for text, label in (
        ('<span class="id">R-S11ak</span>', "Windows SCM service-entry requirement"),
        (
            "Windows service authority begins only after the own-process image connects to SCM",
            "Windows SCM service-entry authority clause",
        ),
        ("<tr><td>159</td>", "Windows SCM service-entry Appendix C row"),
        (
            "Windows service-specific authority preceded SCM ownership and dispatcher failure returned success",
            "Windows SCM service-entry Appendix C disposition",
        ),
    ):
        require_text(requirements, text, label)
    require_text(
        hardening,
        "R-S11e-51 — Windows SCM-owned service entry authority",
        "Windows SCM service-entry hardening ledger",
    )


def validate_smoke_container_authority_contract(sources):
    smoke = sources["smoke"]
    stage = sources["smoke_stage"]
    process_guard = sources["smoke_process_guard"]
    verify = sources["verify"]
    requirements = sources["requirements"]
    hardening = sources["hardening"]

    require_order(
        smoke,
        (
            "readonly DOCKER_BIN=/usr/bin/docker",
            "readonly SMOKE_DOCKER_HOST=unix:///var/run/docker.sock",
            'readonly BUILD_UID="$(id -u)"',
            "smoke: refuses host or container-root execution",
            'readonly SMOKE_DOCKER_SOCKET_ID="$(stat -c',
            "read_smoke_pin()",
            "EXPECTED_IMAGE_ID=$(read_smoke_pin DEV_CHECK_IMAGE_ID)",
            "SMOKE_RUST_VERSION=$(read_smoke_pin RUST_VERSION)",
            "SMOKE_VENDOR_CLOSURE_SHA256=$(read_smoke_pin SHA256_CARGO_VENDOR_CLOSURE_V1)",
            "SMOKE_VENDOR_CONFIG_SHA256=$(read_smoke_pin SHA256_CARGO_VENDOR_CONFIG)",
            "smoke_source_tree_digest() {",
            '[ -z "$(git status --porcelain=v1 --untracked-files=all)" ]',
            'SMOKE_SOURCE_COMMIT="$(git rev-parse --verify \'HEAD^{commit}\')"',
            "SMOKE_ROOT=$(mktemp -d /tmp/rustdesk-smoke.XXXXXXXXXX)",
            'git -c core.hooksPath=/dev/null archive --format=tar "$SMOKE_SOURCE_COMMIT"',
            'readonly SMOKE_SOURCE_TREE_SHA256="$(smoke_source_tree_digest)"',
            "readonly SMOKE_DOCKER_COMMAND=(",
            "smoke_docker_authority()",
            "smoke_docker()",
            "IMAGE_ID=$(smoke_docker image inspect --format '{{.Id}}' \"$EXPECTED_IMAGE_ID\") || {",
            'if [ "$IMAGE_ID" != "$EXPECTED_IMAGE_ID" ]; then',
            "readonly IMAGE_ID",
            "BUILD_RUN=(smoke_docker run",
        ),
        "fixed smoke Docker authority and pinned input resolution precede every container",
    )
    require_exact_count(smoke, '"$EXPECTED_IMAGE_ID"', 3, "exact pinned smoke image authority")
    require_exact_count(smoke, '"$IMAGE_ID"', 7, "every smoke container uses the immutable image ID")
    require_exact_count(smoke, "smoke_docker run", 6, "complete smoke container launch inventory")
    require_exact_count(
        smoke,
        '--mount "type=bind,source=$SMOKE_SOURCE,target=/work,readonly"',
        6,
        "every smoke container uses the exact-commit source snapshot",
    )
    require_exact_count(
        smoke,
        "smoke_docker image inspect",
        1,
        "single fixed-client local image resolution",
    )

    build = extract_between(smoke, "BUILD_RUN=(", "\nRUN=(", "smoke build container")
    runtime = extract_between(smoke, "\nRUN=(", "\nROOT_RUN=(", "smoke portable runtime container")
    root_runtime = extract_between(
        smoke, "\nROOT_RUN=(", "\nLIFECYCLE_RUN=(", "smoke explicit-root runtime container"
    )
    lifecycle = extract_between(
        smoke, "LIFECYCLE_RUN=(", "\nPID_REUSE_RUN=(", "smoke lifecycle container"
    )
    pid_reuse = extract_between(
        smoke, "PID_REUSE_RUN=(", "\nPORT_HEX=", "smoke PID-reuse container"
    )
    sibling = extract_through(
        smoke,
        'docker_out=$(smoke_docker run -d --name "$SIBLING_NAME"',
        "2>&1)",
        "smoke sibling container",
    )
    container_blocks = (build, runtime, root_runtime, lifecycle, pid_reuse, sibling)
    for block, label in zip(
        container_blocks,
        ("build", "portable runtime", "explicit-root runtime", "lifecycle", "PID-reuse", "sibling"),
    ):
        require_text(block, "--network none", f"smoke {label} network isolation")
        require_text(block, "--pull=never", f"smoke {label} implicit-pull refusal")
        require_text(block, '"$IMAGE_ID"', f"smoke {label} immutable image identity")

    for token, label in (
        ('--user "$BUILD_UID:$BUILD_GID"', "numeric non-root build identity"),
        ("--cap-drop ALL", "build capability removal"),
        ("--security-opt no-new-privileges", "build privilege-gain refusal"),
        ("--read-only", "build read-only root"),
        ("--pids-limit 1024", "build PID ceiling"),
        ("--memory 12g", "build memory ceiling"),
        ("--memory-swap 12g", "build no-swap ceiling"),
        ("--cpus 4", "build CPU ceiling"),
        ("/tmp:rw,exec,nosuid,nodev,mode=1777,size=2g", "build scratch ceiling"),
        ("CARGO_HOME=/tmp/smoke-cargo-home", "private Cargo home"),
        ("CARGO_TARGET_DIR=/work/target", "private Cargo target selection"),
        ("CARGO_INCREMENTAL=0", "incremental compilation refusal"),
        ("CARGO_NET_OFFLINE=true", "Cargo network refusal"),
        ("CARGO_NET_RETRY=0", "Cargo retry refusal"),
        ('RUSTUP_TOOLCHAIN=$SMOKE_RUSTUP_TOOLCHAIN', "exact Rust toolchain selection"),
        ('SMOKE_EXPECTED_RUSTUP_TOOLCHAIN=$SMOKE_RUSTUP_TOOLCHAIN', "exact Rust toolchain expectation"),
        ('SMOKE_EXPECTED_VENDOR_CLOSURE_SHA256=$SMOKE_VENDOR_CLOSURE_SHA256', "sealed vendor closure authority"),
        ('SMOKE_EXPECTED_VENDOR_CONFIG_SHA256=$SMOKE_VENDOR_CONFIG_SHA256', "canonical vendor source-map authority"),
        ('--mount "type=bind,source=$SMOKE_SOURCE,target=/work,readonly"', "build read-only exact-commit source"),
        ('--mount "type=bind,source=$SMOKE_ONLINE_ROOT,target=/online,readonly"', "build read-only offline input"),
        ('-v "$SMOKE_BUILD_TARGET:/work/target:rw"', "build private writable target"),
    ):
        require_text(build, token, label)
    require_absent(smoke, '$PWD:/work:', "live-checkout mount authority")
    require_absent(build, "rd-cargo-cache", "mutable smoke build registry cache authority")
    require_absent(build, "rd-git-cache", "mutable smoke build Git cache authority")
    require_absent(build, "/usr/local/cargo/registry", "image-global Cargo registry authority")
    require_absent(build, "/usr/local/cargo/git", "image-global Cargo Git authority")
    require_absent(runtime, "/usr/local/cargo/", "smoke runtime dependency-cache authority")
    require_absent(runtime, "target=/online", "smoke runtime offline-build-input authority")
    for token, label in (
        ('--user "$BUILD_UID:$BUILD_GID"', "numeric non-root portable runtime identity"),
        ("--cap-drop ALL", "portable runtime capability removal"),
        ("--security-opt no-new-privileges", "portable runtime privilege-gain refusal"),
        ("--read-only", "portable runtime read-only root"),
        ("--pids-limit 1024", "portable runtime PID ceiling"),
        ("--memory 4g", "portable runtime memory ceiling"),
        ("--memory-swap 4g", "portable runtime no-swap ceiling"),
        ("--cpus 2", "portable runtime CPU ceiling"),
        ("/tmp:rw,exec,nosuid,nodev,mode=1777,size=1g", "portable runtime scratch ceiling"),
    ):
        require_text(runtime, token, label)
    require_exact_count(
        smoke,
        'if [ "$SMOKE_MODE" = with-root-containers ]; then',
        4,
        "root-container mode guard cardinality",
    )
    require_text(
        smoke,
        'case "$#" in\n  0)\n    SMOKE_MODE=portable-rootless\n    ;;',
        "portable rootless default",
    )
    for block, label in (
        (runtime, "ordinary runtime"),
        (root_runtime, "explicit-root runtime"),
        (lifecycle, "lifecycle"),
        (pid_reuse, "PID-reuse"),
        (sibling, "sibling"),
    ):
        require_text(
            block,
            '--mount "type=bind,source=$SMOKE_SOURCE,target=/work,readonly"',
            f"{label} read-only exact-commit source",
        )
        require_text(
            block,
            '-v "$SMOKE_BUILD_TARGET:/work/target:ro"',
            f"{label} read-only target",
        )

    require_order(
        smoke,
        (
            "case \"$#\" in",
            "SMOKE_MODE=portable-rootless",
            "--with-root-containers) SMOKE_MODE=with-root-containers",
            "readonly SMOKE_MODE",
            "ROOT_RUN=(smoke_docker run",
            'if [ "$SMOKE_MODE" = with-root-containers ]; then',
            'run_stage out2b "${ROOT_RUN[@]}"',
            'run_stage out2c "${ROOT_RUN[@]}"',
            'run_stage out2d "${ROOT_RUN[@]}"',
            'run_stage out9 "${ROOT_RUN[@]}"',
            "SMOKE ROOTLESS OK:",
        ),
        "portable-rootless default and explicit-root stage reachability",
    )
    for token, label in (
        ("portable-rootless mode: root service, PID-reuse, and init-system lifecycle stages not entered", "root lifecycle omission verdict"),
        ("portable-rootless mode: root-owned/user-creation/installed-layout password fixtures not entered", "root password omission verdict"),
        ("portable-rootless mode: packet-capture stage not entered", "root packet-capture omission verdict"),
        ("Root/service/init-system/user-creation/installed-layout/packet-capture, graphical/native/device, performance/soak, and release-artifact evidence were not entered or claimed.", "rootless evidence limit"),
    ):
        require_text(smoke, token, label)

    complete_launch_surface = "\n".join(container_blocks)
    for token, label in (
        ("--network host", "host network"),
        ("--network=host", "host network"),
        ("--publish", "published port"),
        ("--publish-all", "published ports"),
        ("--pid=host", "host PID namespace"),
        ("--privileged", "privileged container"),
        ("/var/run/docker.sock", "Docker socket"),
    ):
        require_absent(complete_launch_surface, token, f"smoke {label} authority")
    if re.search(r"(?m)(?:^|[ \t])-p(?:[ =]|$)", complete_launch_surface):
        raise VerificationError("smoke short-form published port authority: forbidden contract remains present")
    if re.search(r"(?m)(?:^|[ \t])-P(?:[ \t\\]|$)", complete_launch_surface):
        raise VerificationError("smoke short-form published ports authority: forbidden contract remains present")

    for token, label in (
        ("[ -f \"$DOCKER_BIN\" ] && [ ! -L \"$DOCKER_BIN\" ]", "fixed client regular-file proof"),
        ("0:0:755:1", "fixed client owner/mode/link proof"),
        ("[ -S /var/run/docker.sock ] && [ ! -L /var/run/docker.sock ]", "fixed socket type proof"),
        ("SMOKE_DOCKER_SOCKET_ID", "fixed socket identity proof"),
        ("DOCKER_HOST DOCKER_CONTEXT DOCKER_CONFIG", "ambient Docker endpoint/config refusal"),
        ("DOCKER_CERT_PATH DOCKER_TLS_VERIFY DOCKER_TLS", "ambient Docker TLS refusal"),
        ("DOCKER_API_VERSION DOCKER_DEFAULT_PLATFORM DOCKER_CONTENT_TRUST", "ambient Docker API/platform/trust refusal"),
        ("DOCKER_CONTENT_TRUST_SERVER DOCKER_CUSTOM_HEADERS", "ambient Docker trust/header refusal"),
        ("/usr/bin/env -i", "empty Docker client environment"),
        ('--host "$SMOKE_DOCKER_HOST"', "explicit fixed Docker endpoint"),
        ('--config "$SMOKE_DOCKER_CONFIG"', "explicit private Docker configuration"),
        ("printf '{}\\n' >\"$SMOKE_DOCKER_CONFIG/config.json\"", "canonical empty Docker configuration"),
        ('readonly SMOKE_DOCKER_CONFIG_ID="$(stat -c', "private Docker directory identity"),
        ('readonly SMOKE_DOCKER_CONFIG_FILE_ID="$(stat -c', "private Docker config identity"),
        ('readonly SMOKE_BUILD_TARGET_ID="$(stat -c', "private build-target identity"),
        ('readonly SMOKE_SOURCE_ARCHIVE_ID="$(stat -c', "exact source-archive identity"),
        ('readonly SMOKE_SOURCE_ID="$(stat -c', "exact source-snapshot identity"),
        ('= "$SMOKE_DOCKER_CONFIG_FILE_ID" ]', "Docker config identity recheck"),
        ('= "$SMOKE_BUILD_TARGET_ID" ]', "build-target identity recheck"),
        ('= "$SMOKE_SOURCE_ARCHIVE_ID" ]', "source-archive identity recheck"),
        ('= "$SMOKE_SOURCE_ID" ]', "source-snapshot identity recheck"),
        ("verify_smoke_source_snapshot()", "exact source content postcondition"),
        ('= "$SMOKE_SOURCE_TREE_SHA256" ]', "exact source tree digest postcondition"),
        ("smoke_docker_authority || return 1", "Docker authority precondition"),
        ('"${SMOKE_DOCKER_COMMAND[@]}" "$@" || status=$?', "single fixed Docker client invocation"),
        ("preserving changed Docker/build authority", "identity-safe cleanup refusal"),
    ):
        require_text(smoke, token, label)
    require_exact_count(
        smoke,
        'smoke_docker_authority || return 1',
        4,
        "Docker authority pre/post and bounded-wait checks",
    )
    for token in (
        "HOST_GUARD",
        "historical-selector",
        "smoke-process-guard.py record",
        "smoke-process-guard.py monitor",
        "smoke-process-guard.py request-stop",
        "smoke-process-guard.py wait-ready",
    ):
        require_absent(smoke, token, "top-level host process inspection authority")
    if re.search(r"(?m)(?:^|[=( ])docker (?:run|image|inspect|logs|wait|rm)(?:[ )]|$)", smoke):
        raise VerificationError("smoke bypasses the fixed Docker-client authority funnel")

    for token, label in (
        ('case "$name" in', "closed smoke pin reader"),
        ("DEV_CHECK_IMAGE_ID|RUST_VERSION|SHA256_CARGO_VENDOR_CLOSURE_V1|SHA256_CARGO_VENDOR_CONFIG", "complete smoke pin allowlist"),
        ('done < scripts/pins.env', "data-only smoke pin input"),
        ('^${name}=\\"([A-Za-z0-9._:-]+)\\"', "canonical quoted smoke pin grammar"),
        ('readonly SMOKE_RUSTUP_TOOLCHAIN="${SMOKE_RUST_VERSION}.0-x86_64-unknown-linux-gnu"', "exact shipped Rust toolchain derivation"),
    ):
        require_text(smoke, token, label)
    require_absent(smoke, "source scripts/pins.env", "executable smoke pin manifest authority")

    require_order(
        stage,
        (
            "verify_smoke_build_inputs() {",
            "prepare_smoke_cargo_home() {",
            "verify_smoke_build_postconditions() {",
            "  build)",
            "    verify_smoke_build_inputs",
            "    prepare_smoke_cargo_home",
            "    cargo build --locked --offline --features linux-pkg-config",
            "    verify_smoke_build_postconditions",
        ),
        "sealed inputs are verified before and after the exact smoke build",
    )
    require_exact_count(
        stage,
        "verify_smoke_build_inputs",
        3,
        "vendor input pre/post verification cardinality",
    )
    for token, label in (
        ('readonly CARGO_VENDOR_DIR=/online/cargo-vendor', "sealed vendor path"),
        ('readonly CARGO_VENDOR_CONFIG=/online/cargo-vendor-config.toml', "canonical vendor source-map path"),
        ('/usr/bin/python3 -I -S "$CARGO_VENDOR_PROVENANCE" verify-subtree', "isolated vendor provenance verifier"),
        ('--expected "$SMOKE_EXPECTED_VENDOR_CLOSURE_SHA256"', "vendor closure digest binding"),
        ('actual_config_sha=$(/usr/bin/sha256sum -- "$CARGO_VENDOR_CONFIG"', "vendor source-map digest binding"),
        ('[ "${CARGO_HOME:-}" = /tmp/smoke-cargo-home ]', "private Cargo-home refusal"),
        ('[ "${CARGO_TARGET_DIR:-}" = /work/target ]', "private target refusal"),
        ('[ "${CARGO_NET_OFFLINE:-}" = true ]', "Cargo offline environment enforcement"),
        ('[ "${CARGO_INCREMENTAL:-}" = 0 ]', "incremental compilation enforcement"),
        ('[ ! -e "$CARGO_HOME" ] && [ ! -L "$CARGO_HOME" ]', "fresh Cargo-home enforcement"),
        ('/usr/bin/sed \'s#^directory = .*$#directory = "/online/cargo-vendor"#\'', "sealed Cargo directory source map"),
        ('/usr/bin/chmod 0400 -- "$CARGO_HOME/config.toml"', "read-only private Cargo source map"),
        ('SMOKE_CARGO_CONFIG_SHA256=$(/usr/bin/sha256sum -- "$CARGO_HOME/config.toml"', "private Cargo source-map identity"),
        ('= "$SMOKE_CARGO_CONFIG_SHA256" ]', "private Cargo source-map postcondition"),
    ):
        require_text(stage, token, label)

    for token, label in (
        ('"""Prove exact server process identities inside isolated smoke containers."""', "container-only process helper scope"),
        ("def server_argv_is_expected(argv, service_owned):", "closed server-role classifier"),
        ("expected = [NEUTRAL_ARGV0, SERVER_ROLE]", "ordinary exact server role"),
        ("expected.append(SERVICE_OWNED_ROLE)", "service-owned exact argv construction"),
        ("return argv == expected", "closed exact argv comparison"),
        ('commands.add_parser("wait-server")', "ordinary exact identity operation"),
        ('commands.add_parser("wait-service-server")', "service exact identity operation"),
        ('service_owned = ordinary + [SERVICE_OWNED_ROLE]', "service-owned positive role fixture"),
        ('commands.add_parser("self-test")', "pure process-helper self-test"),
        ('fail("non-exact server role fixture was accepted")', "closed-role negative fixture"),
    ):
        require_text(process_guard, token, label)
    for token in (
        "SELECTOR",
        "stable_baseline",
        "scan_matching_processes",
        "new_matches",
        'commands.add_parser("record")',
        'commands.add_parser("monitor")',
        'commands.add_parser("request-stop")',
        'commands.add_parser("wait-ready")',
    ):
        require_absent(process_guard, token, "retired host process-table operation")

    build_stage = extract_between(stage, "  build)\n", "    ;;\n  mdwe)", "smoke Cargo build stage")
    require_text(
        build_stage,
        "cargo build --locked --offline --features linux-pkg-config",
        "smoke locked offline Cargo build",
    )
    require_exact_count(build_stage, "cargo build ", 1, "sole smoke Cargo build")

    requirement = extract_html_requirement(
        requirements, "R-S11ax", "smoke container authority requirement"
    )
    for token, label in (
        ("exact pinned development-image content ID", "exact pinned image requirement"),
        ("<code>--pull=never</code>", "implicit image-pull refusal requirement"),
        ("<code>--network none</code>", "network-none requirement"),
        ("<code>--locked --offline</code>", "locked offline Cargo requirement"),
        ("MUST NOT</span> mount persistent registry or Git caches", "mutable build-cache prohibition"),
        ("full vendor-tree provenance root", "sealed vendor provenance requirement"),
        ("rechecked after Cargo", "build-input postcondition requirement"),
        ("MUST NOT</span> publish ports", "port-publication prohibition"),
        ("build and ordinary portable-runtime containers", "portable runtime non-root requirement"),
        ("all capabilities dropped", "portable runtime capability requirement"),
        ("explicit PID/memory/no-swap/CPU ceilings", "portable runtime resource requirement"),
        ("--portable-rootless", "portable rootless selection requirement"),
        ("--with-root-containers", "explicit root-container selection requirement"),
        ("rootless terminal verdict", "truthful rootless verdict requirement"),
    ):
        require_text(requirement, token, label)
    require_text(requirements, "<tr><td>172</td>", "smoke container authority Appendix C row")
    require_text(
        hardening,
        "R-S11e-64 — smoke container image, network, and dependency authority",
        "smoke container authority hardening ledger",
    )
    authority_requirement = extract_html_requirement(
        requirements, "R-S11dd", "smoke host/build authority requirement"
    )
    for token, label in (
        ("exact root-owned non-symlink <code>/usr/bin/docker</code>", "fixed Docker client requirement"),
        ("authority-root and build-target identities", "private object identity requirement"),
        ("No top-level smoke operation", "host-process inspection prohibition"),
        ("invoking numeric non-root UID/GID", "non-root compile-container requirement"),
        ("fresh current-user-private target bind writable", "private target requirement"),
        ("private read-only exact-commit source snapshot", "exact source-snapshot requirement"),
        ("Every runtime/lifecycle/sibling container", "read-only runtime target requirement"),
        ("R-S11e-122 ledger entry", "hardening-ledger requirement"),
    ):
        require_text(authority_requirement, token, label)
    require_text(requirements, "<tr><td>257</td>", "smoke host/build authority Appendix C row")
    require_text(
        hardening,
        "R-S11dd/R-S11e-122 — runtime-smoke host, Docker-client, build-user, and checkout-write",
        "smoke host/build authority hardening ledger",
    )
    require_text(
        verify,
        "Smoke container and host/build authority (R-S11ax/R-S11dd/R-S11e-64/R-S11e-122)",
        "smoke container authority source gate",
    )


def validate_wayland_capture_source_excision_contract(sources):
    expected_states = (
        ("scrap_wayland_directory_state", "scrap-wayland-directory-absent", "scrap Wayland directory absence"),
        ("scrap_wayland_root_source_state", "scrap-wayland-root-source-absent", "scrap root Wayland source absence"),
        ("scrap_wayland_common_source_state", "scrap-wayland-common-source-absent", "scrap common Wayland source absence"),
    )
    for key, expected, label in expected_states:
        if sources[key] != expected:
            raise VerificationError(f"{label}: forbidden source path remains present")

    try:
        root_manifest = tomllib.loads(sources["root_cargo"])
        scrap_manifest = tomllib.loads(sources["scrap_cargo"])
    except tomllib.TOMLDecodeError as exc:
        raise VerificationError(f"Wayland capture Cargo policy: manifest does not parse: {exc}") from exc
    root_scrap_dependency = root_manifest.get("dependencies", {}).get("scrap")
    root_scrap_features = (
        root_scrap_dependency.get("features", [])
        if isinstance(root_scrap_dependency, dict)
        else []
    )
    if "wayland" in root_scrap_features:
        raise VerificationError("root scrap Wayland feature: forbidden feature activation remains present")
    if "wayland" in scrap_manifest.get("features", {}):
        raise VerificationError("scrap Wayland feature declaration: forbidden feature remains present")
    if re.search(
        r"(?m)^\s*(?:pub\s+)?mod\s+wayland\s*;",
        sources["scrap_lib"] + "\n" + sources["scrap_common_mod"],
    ):
        raise VerificationError("scrap Wayland module declaration: forbidden module remains present")

    for text, label in (
        (
            "[ -e libs/scrap/src/wayland ] || [ -L libs/scrap/src/wayland ]",
            "shared scrap Wayland directory source gate",
        ),
        (
            "[ -e libs/scrap/src/wayland.rs ] || [ -L libs/scrap/src/wayland.rs ]",
            "shared scrap root Wayland source gate",
        ),
        (
            "[ -e libs/scrap/src/common/wayland.rs ] || [ -L libs/scrap/src/common/wayland.rs ]",
            "shared scrap common Wayland source gate",
        ),
        (
            "R-X12/R-X12a Wayland/pipewire capture feature, module declarations, directory, and orphaned source files absent",
            "shared Wayland source-excision success marker",
        ),
    ):
        require_text(sources["verify"], text, label)

    requirement = extract_html_requirement(
        sources["requirements"], "R-X12a", "Wayland capture source deletion requirement"
    )
    for text, label in (
        ("Delete the uncompiled Wayland capture source residue", "Wayland source deletion title"),
        ("libs/scrap/src/wayland.rs", "root Wayland source path requirement"),
        ("libs/scrap/src/common/wayland.rs", "common Wayland source path requirement"),
        ("MUST</span> remain absent", "Wayland source absence requirement"),
    ):
        require_text(requirement, text, label)
    require_text(
        sources["requirements"],
        "<tr><td>192</td>",
        "Wayland capture source residue Appendix C row",
    )
    require_text(
        sources["hardening"],
        "R-X12a — orphaned Wayland capture source files deleted",
        "Wayland capture source residue hardening ledger",
    )

    mutation_matrix = extract_between(
        sources["workspace_verifier"],
        "def run_source_mutations(sources):\n    mutations = (",
        "\n    )\n    for key, old, new, expected in mutations:",
        "Wayland source deletion deliberate-mutation matrix",
    )
    for text, label in (
        ("root scrap Wayland feature", "root feature mutation"),
        ("scrap Wayland feature declaration", "crate feature mutation"),
        ("scrap Wayland module declaration", "module declaration mutation"),
        ("scrap Wayland directory absence", "directory-state mutation"),
        ("scrap root Wayland source absence", "root-source-state mutation"),
        ("scrap common Wayland source absence", "common-source-state mutation"),
        ("shared scrap Wayland directory source gate", "directory-gate mutation"),
        ("shared scrap root Wayland source gate", "root-source-gate mutation"),
        ("shared scrap common Wayland source gate", "common-source-gate mutation"),
        ("Wayland capture source deletion requirement", "requirement mutation"),
        ("Wayland capture source residue Appendix C row", "Appendix mutation"),
        ("Wayland capture source residue hardening ledger", "hardening-ledger mutation"),
    ):
        require_text(mutation_matrix, text, label)


